Translate("deDE", "tanaris", {
	title = "Tanaris",
	aliases = { "die Wüste Tanaris", "Wüste von Tanaris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tanaris ist die große Wüste im Süden von {link:kalimdor}Kalimdor{/link}. Ihre Dünen reichen von den Klippen von {link:thousand-needles}Tausend Nadeln{/link} bis zum südlichen Meer und vom grünen Rand des {link:un-goro-crater}Un'Goro-Kraters{/link} bis zu einer Küste warmer Strände und verborgener Buchten. Regen fällt fast nie. Jeder Brunnen ist einen Mord wert, und jedes Wasserloch lockt etwas Durstiges an. Im Norden steht {link:gadgetzan}Gadgetzan{/link}, eine ummauerte Goblinstadt, die aus Wasser ein Geschäft gemacht hat. Ringsum bewahrt der Sand ältere Dinge: die zerbrochenen Tempel der {link:trolls}Trolle{/link}, die versiegelten Steintore eines Ortes namens {link:valley-of-the-watchers}Uldum{/link} und eine große Höhle in den östlichen Klippen, in der die Drachen der Zeit wohnen sollen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik sagt, wann das Land zur Wüste wurde oder was es zuvor war. Die {link:trolls}Trolle{/link} sind seine ältesten bekannten Herren. In den Tagen ihres Reiches errichtete ein Stamm von Wüstentrollen die Stadt {red:zul-farrak}Zul'Farrak{/red} zwischen den nördlichen Dünen und verstreute Schreine und Siedlungen über den Sand im Süden und Osten. Die meisten davon liegen heute in Trümmern. Noch älter sind die Werke der Titanen. Im Südwesten, im {link:valley-of-the-watchers}Tal der Behüter{/link}, stehen riesige Statuen vor versiegelten Toren, die keine lebende Hand je geöffnet hat, und Gelehrte, die die Scheiben von {link:uldaman}Uldaman{/link} erforschen, glauben, dass jene Tore und die Aufzeichnungen der Titanen miteinander verbunden sind.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Tanaris gehört dem, der Wasser halten kann. Die Goblins des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} beherrschen {link:gadgetzan}Gadgetzan{/link}, und ihre {link:gadgetzan-water-company}Wassergesellschaft{/link} pumpt die Brunnen der Stadt. Außerhalb der Mauern haben {link:wastewander-nomads}die Nomaden{/link} der Wastewander fast jeden anderen Brunnen der Wüste an sich gerissen. Nun ist etwas Schlimmeres gekommen. Schwärme von Insekten sind im Westen und Süden aus dem Sand gestiegen, und sie saugen die Wasserlöcher leer. Die Gelehrten von Gadgetzan nennen sie die {link:qiraji}Sillithid{/link}, und sie fürchten, dass ein Geist hinter ihnen steht. {link:ogres}Oger{/link} der Dünenbrecher haben in der südlichen Öde ein Lager errichtet. Die {link:sandfury-trolls}Trolle der Sandfury{/link} beobachten alles von Zul'Farrak aus. An der Küste halten {link:southsea-pirates}Südmeerpiraten{/link} eine ummauerte Bucht, nur einen kurzen Fußweg südlich vom Hafen des Kartells.

Das Kartell ist nicht untätig. Seine Schiffe segeln noch immer von {link:steamwheedle-port}Steamwheedle{/link} nach {link:booty-bay}Booty Bay{/link}, und eine neuere Route bringt sie nach {link:powderfuse-port}Powderfuse Port{/link} in den {link:riverglades}Riverglades{/link}, auf der anderen Seite des Meeres.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Goblins von {link:gadgetzan}Gadgetzan{/link}.{/b} Ingenieure, Alchemisten, Schmiede und Händler, die an jeden verkaufen, und deren Schläger dafür sorgen, dass innerhalb der Mauern niemand kämpft.
• {b}Die {link:wastewander-nomads}Nomaden der Wastewander{/link}.{/b} Banditen und Diebe des östlichen Sandes, die die Brunnen halten und das Wasser an die Durstigen zurückverkaufen.
• {b}Die {link:sandfury-trolls}Trolle der Sandfury{/link}.{/b} Der Wüstenstamm von Zul'Farrak und der Ruinen ringsum, bekannt für Grausamkeit und dunkle Magie.
• {b}Die Sillithid.{/b} Insekten der Stöcke der Centipaar, die ihre Nester im Giftigen Unterschlupf und in der Klaffenden Schlucht gegraben haben.
• {b}Die {link:ogres}Oger{/link} der Dünenbrecher.{/b} Eine Schar von Nomaden, neu in die südliche Wüste gekommen.
• {b}Die {link:southsea-pirates}Südmeerpiraten{/link}.{/b} Freibeuter, die von der {link:lost-rigger-cove}Lost-Rigger-Bucht{/link} aus Schiffe des Kartells überfallen.
• {b}Tiere des Sandes.{/b} Basilisken mit Häuten wie Glas, Skorpide, Hyänen, große Feuervögel und die wandelnden Distelsträucher des Südwestens.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Trollreich.{/b} Die Wüstentrolle erbauten Zul'Farrak und verehrten eine große Hydra, die sie Gahz'rilla nannten. Geschnitzte Schmuckstücke dieses Gottes liegen noch im Sand ihrer alten Siedlungen vergraben.
• {b}Die Ankunft des Kartells.{/b} In späteren Zeitaltern kamen die Goblins des {link:steamwheedle-port}Steamwheedle{/link}-Kartells in die Wüste und erbauten {link:gadgetzan}Gadgetzan{/link} und Steamwheedle. Keine Chronik verzeichnet das Jahr.
• {b}Die Gegenwart.{/b} Die Brunnen sind verloren, die Insekten erheben sich, und die Stadt, die Wasser verkauft, hat begonnen, jedes Schwert anzuheuern, das sie finden kann.]=],
		},
		{
			title = "Kunde des Sandes",
			text = [=[• Reisende, die in der Wüste nahe {link:gadgetzan}Gadgetzan{/link} sterben, werden auf einem kleinen Friedhof vor seinen Mauern begraben. Es heißt, ein Geist namens Gaeriyan warte in den Hügeln im Norden und spreche nur mit jenen, die hinübergegangen sind.
• Tooga, eine verirrte Schildkröte, wandert durch die Wüste auf der Suche nach seiner Frau Torta, die südlich von {link:steamwheedle-port}Steamwheedle{/link} auf ihn wartet.
• Die Goblins von Gadgetzan sagen, der Rum von Steamwheedle sei so dick wie Kies und brenne wie Lava. Sie meinen es als Lob.]=],
		},
	},
})

Translate("deDE", "gadgetzan", {
	title = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gadgetzan ist die Goblinhauptstadt der Wüste, eine ummauerte Stadt im Norden von {link:tanaris}Tanaris{/link}. Das {link:steamwheedle-cartel}Steamwheedle-Kartell{/link} hat sie erbaut, und wie ihre Schwesterhäfen steht sie {link:alliance}Allianz{/link} und {link:horde}Horde{/link} gleichermaßen offen. Die Schläger von Gadgetzan gehen durch ihre Straßen und verfahren hart mit jedem, der eine Klinge zieht. Die Stadt lebt von ihrem Wasserturm und ihren Brunnen, die von der {link:gadgetzan-water-company}Wassergesellschaft von Gadgetzan{/link} unterhalten werden. Um sie herum drängen sich das Gizmorium, Schmieden, ein Gasthaus, eine Bank und die Werkstätten meisterlicher Goblin-Ingenieure. Greifen und Windreiter landen hier Seite an Seite.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Im Gasthaus spricht man von verlorenen Brunnen, Kopfgeldern auf Nomaden und seltsamen Käfern im Westen. Gelehrte kommen, um zu kaufen, was die Goblins wissen. Schmiede kommen wegen der Gussformen von {link:krinkle-goodsteel}Krinkle Goodsteel{/link}, und der Stoffhändler {link:vizzklick}Vizzklick{/link} freut sich noch immer über den Tod von {link:trade-master-kovic}Handelsmeister Kovic{/link}.]=],
		},
	},
})

Translate("deDE", "steamwheedle-port", {
	title = "Steamwheedle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Steamwheedle ist der Hafen des Kartells an der Ostküste von {link:tanaris}Tanaris{/link}. Seine Schiffe bringen Fracht nach {link:booty-bay}Booty Bay{/link}, und die Piraten der Küste führen Listen darüber, welche davon sich zu kapern lohnen. {link:security-chief-bilgewhizzle}Sicherheitschef Bilgewhizzle{/link} ist damit betraut, den Frieden zu wahren. {link:stoley}Stoley{/link} schenkt den berühmten Bilgenrum des Hafens aus, und ein Trollgelehrter namens {link:yeh-kinya}Yeh'kinya{/link} studiert alte Prophezeiungen zwischen den Kisten. In diesen Tagen schickt ein Kaimeister außerdem Schiffe über das Meer nach {link:powderfuse-port}Powderfuse Port{/link}. Südlich des Hafens, in Sichtweite der Docks, liegt die {link:lost-rigger-cove}Lost-Rigger-Bucht{/link}.]=],
		},
	},
})

Translate("deDE", "lost-rigger-cove", {
	title = "Lost-Rigger-Bucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Lost-Rigger-Bucht ist eine Piratenstadt an der Ostküste von {link:tanaris}Tanaris{/link}, mit Holz ummauert und auf einem schmalen Strand unterhalb der Klippen gelegen. Die {link:southsea-pirates}Südmeerpiraten{/link} halten hier ihre Schiffe und ihre Beute. Von der Bucht aus überfallen sie die Schiffe des Kartells. Hier versteckte Kapitän Cuergo den Rum, den er aus {link:steamwheedle-port}Steamwheedle{/link} gestohlen hatte, und hier lebt {link:andre-firebeard}Andre Firebeard{/link}, der Pirat, auf dessen Kopf das Kartell einen Preis ausgesetzt hat.]=],
		},
	},
})

Translate("deDE", "caverns-of-time", {
	title = "Die Höhlen der Zeit",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[In den östlichen Bergen von {link:tanaris}Tanaris{/link} öffnet sich eine gewaltige Höhle im Fels. Man nennt sie die Höhlen der Zeit. Alte Geschichten sagen, sie sei der Hort der {red:bronze-dragonflight}bronzenen Drachen{/red} und ihres Herrn {red:nozdormu}Nozdormu{/red}, des Zeitlosen, den die Titanen damit betrauten, über die Pfade der Zeit zu wachen. Kein Reisender dieser Tage hat berichtet, was darin liegt.]=],
		},
	},
})

Translate("deDE", "valley-of-the-watchers", {
	title = "Tal der Behüter",
	aliases = { "Uldum", "die versiegelten Tore von Uldum" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Tal der Behüter liegt im Südwesten von {link:tanaris}Tanaris{/link}. Riesige Steinfiguren der Titanen stehen dort im Sand, und zwischen ihnen erheben sich große versiegelte Tore. Die Gelehrten von {link:thunder-bluff}Thunder Bluff{/link} glauben, dass die Tore nach Uldum führen, einem Ort, den die meisten für einen Mythos halten. Vor den Toren steht ein Sockel. Wenn die Platinscheiben von {link:uldaman}Uldaman{/link} zu ihm gebracht werden, erscheint ein {link:stone-watcher-of-norgannon}Steinwächter von Norgannon{/link} und verweigert allen den Zutritt, denen die Platten von Uldum fehlen. In der Nähe, an Gunstans Posten, unterhält ein Prospektor der {link:explorers-league}Forscherliga{/link} sein Lager.]=],
		},
	},
})

Translate("deDE", "thistleshrub-valley", {
	title = "Disteltal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Disteltal ist ein Kakteengarten im Westen von {link:tanaris}Tanaris{/link}, wo die Dünen auf die Klippen unterhalb des {link:un-goro-crater}Un'Goro-Kraters{/link} treffen. Seine Pflanzen gehen umher. Knorrige Distelsträucher und ihre Wurzelformer bewachen {link:stranglethorn-vale}das Tal{/link}, und Tausammler speichern Wasser in ihren Drüsen. Aus einer dieser Drüsen braute {link:marin-noggenfogger}Marin Noggenfogger{/link} sein Elixier. Der Troll {link:tran-rek}Tran'rek{/link} wünscht sich schon lange, in das Tal zu gelangen, aber nicht so sehr, dass er selbst hinginge.]=],
		},
	},
})

Translate("deDE", "eastmoon-ruins", {
	title = "Ruinen von Eastmoon",
	aliases = { "Southmoon-Ruinen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Eastmoon und die Southmoon-Ruinen sind die Überreste von Trollsiedlungen inmitten der Wüste, weit südlich von Zul'Farrak. Von ihrem Volk ist nichts geblieben als zerbrochener Stein. Schatzsucher graben hier nach kleinen Schnitzereien der Hydra Gahz'rilla, gefertigt aus einem seltsamen Stein, den der Goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} Gahz'ridian nennt. In diesen Tagen sind umherziehende Scharen der {link:ogres}Oger{/link} der Dünenbrecher in die Ruinen gezogen.]=],
		},
	},
})

Translate("deDE", "broken-pillar", {
	title = "Zerbrochene Säule",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zerbrochene Säule ist eine einsame Ruine im Herzen von {link:tanaris}Tanaris{/link}, eine zerschmetterte Säule, die die alten Trollbaumeister hinterließen. Hier hat der Goblingelehrte {link:marvon-rivetseeker}Marvon Rivetseeker{/link} sein Lager aufgeschlagen. Er reiste von {link:ratchet}Ratchet{/link} in die Wüste, um zu erfahren, was ihre gefallenen Trollstädte lehren können, und wer vom {link:temple-of-atal-hakkar}Versunkenen Tempel{/link} hören will, muss ihn hier aufsuchen.]=],
		},
	},
})

Translate("deDE", "sandsorrow-watch", {
	title = "Sandsorrow-Wache",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Sandsorrow-Wache ist ein Trollaußenposten im Nordwesten von {link:tanaris}Tanaris{/link}, zwischen {link:gadgetzan}Gadgetzan{/link} und Zul'Farrak. Die {link:sandfury-trolls}Trolle der Sandfury{/link} halten ihn als Wachposten für ihre Stadt. Daneben liegt eines der seltenen Süßwasserbecken der Wüste. Als ein Vermesser der {link:gadgetzan-water-company}Wassergesellschaft von Gadgetzan{/link} kam, um dieses Becken zu prüfen, stieg etwas aus dem Sand und griff an. Es war das erste Zeichen, dass die Insekten des Westens so weit nach Norden vorgedrungen waren.]=],
		},
	},
})

Translate("deDE", "dunemaul-compound", {
	title = "Truppenlager der Dünenbrecher",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Truppenlager der Dünenbrecher ist ein Ogerlager in der südlichen {link:tanaris}Wüste von Tanaris{/link}. Eine große Schar nomadischer {link:ogres}Oger{/link} kam vor nicht langer Zeit hier an und ummauerte ein weites Stück Sand. Ihr Anführer ist {link:gor-marok-the-ravager}Gor'marok der Verwüster{/link}. Kleinere Scharen ziehen vom Lager aus durch die Wüste. {link:gadgetzan}Gadgetzan{/link} fürchtet, dass die Oger Kräfte sammeln, und würde gut dafür bezahlen, sie gebrochen zu sehen, bevor es so weit ist.]=],
		},
	},
})

Translate("deDE", "the-noxious-lair", {
	title = "Der giftige Unterschlupf",
	aliases = { "Giftiger Unterschlupf" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der giftige Unterschlupf ist ein Stock der Centipaar-Insekten im Westen von {link:tanaris}Tanaris{/link}. Bevor sie kamen, lagen hier Wasserbecken. Die Insekten haben sie leergesaugt. Ihre Tunnel wimmeln von Arbeitern, Wespen und Stechern, und die Goblins, die als Erste ihre Körper untersuchten, stellten fest, dass diese Kreaturen allem unähnlich waren, was sie je gesehen hatten, als triebe sie ein fremder Wille. Hier erfuhren die Gelehrten von {link:gadgetzan}Gadgetzan{/link} zum ersten Mal den Namen der {link:qiraji}Sillithid{/link}.]=],
		},
	},
})

Translate("deDE", "the-gaping-chasm", {
	title = "Die klaffende Schlucht",
	aliases = { "Klaffende Schlucht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die klaffende Schlucht ist ein tiefer Riss im Sand südöstlich von {link:gadgetzan}Gadgetzan{/link}. Die Centipaar haben darin einen zweiten Stock angelegt, was den Goblins zeigte, dass die Insekten nicht eine Gegend der Wüste hielten, sondern zwei. Jungvermesser Scrimshank zog aus, um die Schlucht zu kartieren, und kehrte nie zurück. Nur seine Vermessungsausrüstung wurde gefunden. Auch ein gnomischer Heimkehrroboter stürzte nahe ihrem Rand ab, weit entfernt von seinem Erbauer in {link:booty-bay}Booty Bay{/link}.]=],
		},
	},
})

Translate("deDE", "waterspring-field", {
	title = "Waterspring-Feld",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Waterspring-Feld ist ein Abschnitt der östlichen Wüste, wo einst die Brunnen der {link:gadgetzan-water-company}Wassergesellschaft von Gadgetzan{/link} standen. Die {link:wastewander-nomads}Nomaden der Wastewander{/link} rissen sie an sich, und sie halten sie noch immer. Ihre Banditen und Diebe lagern neben den gestohlenen Pumpen, und ihre Schattenmagier und Meuchler halten weiter östlich und südlich Wache. Die Wassergesellschaft betrachtet jeden dieser Brunnen als ihr Eigentum, und sie hat einen Preis auf den Kopf des Anführers der Nomaden ausgesetzt.]=],
		},
	},
})

Translate("deDE", "gadgetzan-water-company", {
	title = "Wassergesellschaft von Gadgetzan",
	aliases = { "Wasserges. Gadgetzan", "Wassergesellschaft", "die Wassergesellschaft" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Wassergesellschaft von Gadgetzan unterhält die Brunnen und Pumpen von {link:gadgetzan}Gadgetzan{/link}, und in einer Wüste macht sie das zum wichtigsten Unternehmen in {link:tanaris}Tanaris{/link}. Ihre Ingenieure graben die Wasserlöcher, ihre Zapfhahnbediener betreiben den Turm, und ihre Vermesser suchen den Sand nach neuen Quellen ab. Sie verkauft Wasser, wie sie alles verkauft: zu einem Preis.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die Gesellschaft liegt im Krieg. Die {link:wastewander-nomads}Nomaden der Wastewander{/link} haben fast alle ihre Brunnen jenseits der Mauern an sich gerissen, ihre Arbeiter ermordet und ihre Vorräte gestohlen. {link:chief-engineer-bilgewhizzle}Chefingenieur Bilgewhizzle{/link} hat Kopfgelder auf die Nomaden und auf ihren Anführer, {link:caliph-scorpidsting}Kalif Scorpidsting{/link}, ausgesetzt, und Zapfhahnbediener Luglunket bezahlt für jeden Wasserbeutel, der ihnen wieder abgenommen wird. Unterdessen schickt {link:senior-surveyor-fizzledowser}Obervermesser Fizzledowser{/link} Jungvermesser aus, um neues Wasser zu finden, und sie haben Schlimmeres als Nomaden gefunden. Insekten saugen die freien Becken des Westens leer, und einer der Vermesser der Gesellschaft ist bereits in der Klaffenden Schlucht gestorben. Die Gesellschaft, die für gewöhnlich verkauft, was sie erfährt, hat beschlossen, ihren Bericht über die Insekten jedem zu schenken, der ihn lesen will.]=],
		},
		{
			title = "Aufbau",
			text = [=[• {b}{link:chief-engineer-bilgewhizzle}Chefingenieur Bilgewhizzle{/link}{/b} führt den Kampf der Gesellschaft um ihre Brunnen.
• {b}{link:senior-surveyor-fizzledowser}Obervermesser Fizzledowser{/link}{/b} leitet die Suche nach neuem Wasser.
• {b}Zapfhahnbediener Luglunket{/b} betreut den Wasserturm und seine Kopfgelder.
• {b}{link:security-chief-bilgewhizzle}Sicherheitschef Bilgewhizzle{/link}{/b} aus {link:steamwheedle-port}Steamwheedle{/link} trägt den Titel Sicherheitsdienst der Wassergesellschaft.]=],
		},
	},
})

Translate("deDE", "wastewander-nomads", {
	title = "Nomaden der Wastewander",
	aliases = { "Wastewander", "Wastewander-Nomaden", "die Nomaden" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nomaden der Wastewander sind die Gesetzlosen der östlichen {link:tanaris}Wüste von Tanaris{/link}. Sie sind Banditen, Diebe und Mörder, und sie haben getan, was keine Armee vermochte: Sie haben den Goblins das Wasser von Tanaris genommen. Fast jeder Brunnen außerhalb der Mauern von {link:gadgetzan}Gadgetzan{/link} gehört ihnen. Sie tragen das Wasser in Beuteln fort und leben davon, während die Stadt, die die Brunnen gebaut hat, Energiequellen kaufen und Kopfgelder zahlen muss, um sie zurückzugewinnen.]=],
		},
		{
			title = "Ränge",
			text = [=[• {b}Banditen und Diebe{/b} halten die nächstgelegenen Brunnen östlich von {link:gadgetzan}Gadgetzan{/link}.
• {b}Schurken, Meuchler und Schattenmagier{/b} sind die stärkeren Ränge und halten sich weiter östlich und südöstlich.
• {b}{link:caliph-scorpidsting}Kalif Scorpidsting{/link}{/b} führt sie alle an.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die {link:gadgetzan-water-company}Wassergesellschaft{/link} nennt sie Besetzer und Mörder. Sie hat Fremde angeheuert, um ihre Zahl zu verringern, und hofft, dass der Tod ihres Anführers sie endlich von den Brunnen vertreibt.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, woher die Wastewander kamen oder wann sie zum ersten Mal in die Wüste zogen.]=],
		},
	},
})

Translate("deDE", "southsea-pirates", {
	title = "Südmeerpiraten",
	aliases = { "Südmeer", "Südmeerpirat", "Südmeerfreibeuter", "die Südmeerpiraten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Südmeerpiraten sind Freibeuter der südlichen Meere. Von verborgenen Häfen aus überfallen sie die Handelsküsten von {link:kalimdor}Kalimdor{/link}, und ihre liebste Beute sind die Schiffe des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link}. In {link:tanaris}Tanaris{/link} halten sie die {link:lost-rigger-cove}Lost-Rigger-Bucht{/link}, eine ummauerte Stadt am Strand südlich von {link:steamwheedle-port}Steamwheedle{/link}. Eine andere Schar von ihnen plagt die Küste südlich von {link:ratchet}Ratchet{/link} im {link:the-barrens}Brachland{/link}.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die Piraten der {link:lost-rigger-cove}Lost-Rigger-Bucht{/link} haben den Rum von {link:steamwheedle-port}Steamwheedle{/link} gestohlen und tragen die Fahrpläne des Hafens bei sich, versehen mit Notizen, welche Schiffe gute Beute brachten und welche sich hart wehrten. Ihr Kapitän {link:andre-firebeard}Andre Firebeard{/link} wird von Steamwheedle und {link:gadgetzan}Gadgetzan{/link} gemeinsam gesucht. Es heißt, das Kartell habe die Piraten einst dafür bezahlt, seine Schiffe in Ruhe zu lassen, und die Piraten hätten begonnen, das Geld zu nehmen und trotzdem zu plündern.]=],
		},
	},
})

Translate("deDE", "sandfury-trolls", {
	title = "Trolle der Sandfury",
	aliases = { "Sandfury", "Sandfury-Trolle", "der Stamm der Sandfury" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Sandfury sind die {link:trolls}Trolle{/link} der Wüste. Ihre Stadt ist {red:zul-farrak}Zul'Farrak{/red} im Nordwesten von {link:tanaris}Tanaris{/link}, und ihre Krieger halten von Außenposten wie der {link:sandsorrow-watch}Sandsorrow-Wache{/link} aus Wache. Sie sind bekannt für ihre Grausamkeit und für eine dunkle Mystik, die ihre Toten erweckt, damit sie ihnen dienen. Sie verehren Gahz'rilla, eine große Hydra, die sie aus einem heiligen Becken im Herzen ihrer Stadt herbeirufen.]=],
		},
		{
			title = "Ihre Künste",
			text = [=[Die Sandfury stellen aus dem Sandstein der Wüste ein Härtemittel her, das von Schmieden geschätzt wird, die gutes Metall kennen. In ihrer Stadt wimmelt es von Skarabäen, denn kein Troll jagt sie dort wegen ihrer Panzer. Alte Tafeln des Propheten Mosh'aru, die vor langer Zeit dorthin gebracht wurden, werden von ihren Priestern verwahrt.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die Sandfury haben keine Freunde in der Wüste. Goblinschmiede und Gelehrte bezahlen für das, was sich aus ihrer Stadt holen lässt, und Scharen von Schatzsuchern ziehen hinein, um ihre Reichtümer zu holen. Nicht alle kommen wieder heraus.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik dieser Tage erzählt, wie lange die Sandfury Zul'Farrak schon halten oder welche Bande sie mit den anderen Trollstämmen pflegen.]=],
		},
	},
})

Translate("deDE", "marin-noggenfogger", {
	title = "Marin Noggenfogger",
	subtitle = "Herr von Gadgetzan",
	found = "Gadgetzan, im Herzen der Stadt",
	hint = "Sucht den Goblin, der Gadgetzan regiert.",
	allegiance = "Gadgetzan · Steamwheedle-Kartell",
	aliases = { "Noggenfogger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marin Noggenfogger ist der Goblinherr von {link:gadgetzan}Gadgetzan{/link}, der Stadt, die das {link:steamwheedle-cartel}Steamwheedle-Kartell{/link} in der {link:tanaris}Wüste von Tanaris{/link} errichtete. Wo {link:baron-revilgaz}Baron Revilgaz{/link} über {link:booty-bay}Booty Bay{/link} herrscht und {link:gazlowe}Gazlowe{/link} über {link:ratchet}Ratchet{/link} wacht, hält Noggenfogger die Wüstenstadt des Kartells. Er ist rastlos, durstig und stets auf der Jagd nach der nächsten großen Idee. Selbst seine Freunde nennen ihn exzentrisch.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:gadgetzan}Gadgetzan{/link} liegt am einzigen sicheren Wasser auf viele Meilen, und sein Herr herrscht an der Kreuzung aller Straßen des Südens. Unter Noggenfogger ist die Stadt neutraler Boden geblieben. {link:alliance}Allianz{/link} und {link:horde}Horde{/link} rasten gleichermaßen hinter ihren Mauern, und die Schläger der Stadt wahren den Frieden. Sein Name ist zudem weit über die Wüste hinaus bekannt, dank des Elixiers, das ihn trägt und mit dem er sein Glück zu machen gedenkt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er regiert {link:gadgetzan}Gadgetzan{/link} für das {link:steamwheedle-cartel}Steamwheedle-Kartell{/link}.
• Er hörte von seltsamen Wüstenkreaturen, die Wasser in ihren Drüsen speichern, und machte sich daran, daraus ein Getränk zu brauen.
• Mit der Hilfe seiner Freundin {link:sprinkle}Sprinkle{/link} schuf er das Noggenfogger-Elixier.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, wie Noggenfogger dazu kam, über {link:gadgetzan}Gadgetzan{/link} zu herrschen, oder wer vor ihm herrschte.]=],
		},
	},
	chapters = {
		{
			title = "Der durstige Goblin",
			hint = [=[Bringt dem durstigen Herrn von Gadgetzan, was der Kakteengarten verbirgt.]=],
			text = [=[Noggenfoggers Durst war so groß, dass er verzweifelte. Er hatte von den Tausammlern des Disteltals gehört, und er folgerte, dass das Wasser in ihren Drüsen ihn endlich stillen könnte. Als ihm eine gefüllte Drüse gebracht wurde, trank er sie sofort. Es schmeckte scheußlich. Beinahe hätte er aufgegeben, bis er beschloss, dass ein so schlechtes Getränk wenigstens etwas Wumms haben sollte.]=],
		},
		{
			title = "Das Elixier",
			hint = "Helft dem Goblin, sein Getränk zu vervollkommnen.",
			text = [=[{link:sprinkle}Sprinkle{/link}, die Köchin von {link:gadgetzan}Gadgetzan{/link}, kannte ein Geheimnis: einen violetten Pilz, der unter dem Wasser eines kleinen Sees im {link:the-hinterlands}Hinterland{/link} wächst. Zu Pulver gemahlen und mit dem Tau vermischt, machte er das Gebräu nicht nur trinkbar, sondern wunderbar. Noggenfogger verkündete, er werde damit Millionen verdienen. Als er hörte, dass er Sprinkle einen Gefallen schulde, nannte er sie eine große Spaßmacherin.]=],
		},
	},
	mentions = {
		{ text = "Guter Geschmack" },
		{ text = "Sprinkles geheime Zutat" },
		{ text = "Lieferung für Marin" },
	},
	bonds = {
		{ id = "sprinkle", name = "Sprinkle", note = "seine Freundin und Köchin" },
		{ id = "chief-engineer-bilgewhizzle", name = "Chefingenieur Bilgewhizzle", note = "hütet das Wasser der Stadt" },
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "herrscht für dasselbe Kartell über Booty Bay" },
		{ id = "gazlowe", name = "Gazlowe", note = "herrscht für dasselbe Kartell über Ratchet" },
	},
})

Translate("deDE", "yeh-kinya", {
	title = "Yeh'kinya",
	subtitle = "Gelehrter der Trollprophezeiungen",
	found = "Steamwheedle",
	hint = [=[Sucht den Troll, der zwischen den Kisten von Steamwheedle alte Prophezeiungen studiert.]=],
	allegiance = "Unbekannt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Yeh'kinya ist ein Troll, der unter den Goblins von {link:steamwheedle-port}Steamwheedle{/link} lebt. Er kennt die alten Legenden seines Volkes besser als die meisten, vor allem die Legende von {link:hakkar}Hakkar{/link} dem Seelenschinder, dem toten Gott des Blutes. Er sagt, er glaube nicht an die Geschichten von Hakkars Rückkehr. Er glaubt aber, dass die Essenz des Gottes große Macht birgt, und er hat sich aufgemacht, sie zu sammeln.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Yeh'kinya ist derjenige, der die Sache mit dem Ei von {link:hakkar}Hakkar{/link} in Gang setzte. Durch die Geister von Tieren, die Tafeln eines toten Propheten und ein in einer Trollstadt verborgenes Ei erfuhr er, wie die Essenz des Seelenschinders eingefangen und gehalten werden könnte. Er spricht davon, sie vor jenen zu bewahren, die sie missbrauchen würden. Nicht jeder glaubt ihm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er suchte die Geister der Talkreischer von {link:feralas}Feralas{/link}, die er Vettern eines alten Gottes nennt.
• Er sammelte die ersten beiden Tafeln des Propheten Mosh'aru aus {red:zul-farrak}Zul'Farrak{/red} und verschmolz sie miteinander.
• Er ließ ein uraltes Ei aus {link:jintha-alor}Jintha'Alor{/link} holen, ein Relikt der Trollreiche.
• Er schickte das Ei in den {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link}, wo die Essenz des Gottes eingefangen wurde.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, aus welchem Stamm Yeh'kinya stammt oder warum er unter Goblins lebt.]=],
		},
	},
	chapters = {
		{
			title = "Kreischergeister",
			hint = [=[Bringt dem Troll von Steamwheedle die Geister der Kreischer von Feralas.]=],
			text = [=[Yeh'kinya wollte die Geister der Talkreischer, denn er hielt sie für verbunden mit einem uralten Gott. Als sie ihm gebracht wurden, erzählte er von einer alten Trollprophezeiung: dass der tote Gott {link:hakkar}Hakkar{/link} eines Tages in die Welt zurückkehren werde. Manche {link:trolls}Trolle{/link} sagen, dies werde Ruhm bringen. Andere sagen, es werde das Ende aller Dinge bringen.]=],
		},
		{
			title = "Die Prophezeiung von Mosh'aru",
			hint = "Bringt dem Troll die Tafeln des Propheten aus Zul'Farrak.",
			text = [=[Die Prophezeiung von Mosh'aru wurde auf zwei Tafeln geschrieben und nach Zul'Farrak gebracht. Eine wurde von dem toten Troll Theka dem Märtyrer gehalten, die andere von der Hydromantin Velratha neben dem heiligen Becken. Yeh'kinya verschmolz die Tafeln und las ihr Geheimnis: Ein uraltes Ei könne die Essenz Hakkars aufnehmen.]=],
		},
		{
			title = "Das Ei von Hakkar",
			hint = [=[Tragt das Ei in den versunkenen Tempel und bringt es gefüllt zurück.]=],
			text = [=[Das Ei wurde in {link:jintha-alor}Jintha'Alor{/link} gefunden und in das Sanktum des gefallenen Gottes getragen. Der {link:avatar-of-hakkar}Avatar von Hakkar{/link} trat hervor und fiel, und seine Essenz wurde in dem Ei versiegelt. Als das Ei nach {link:tanaris}Tanaris{/link} zurückkam, regte sich Leben darin. Yeh'kinya wirkte erschüttert, und er schwor, es vor bösen Händen zu bewahren.]=],
		},
		{
			title = "Die verlorenen Tafeln",
			hint = "Hört, was der Zwerg von Steamwheedle erfahren hat.",
			text = [=[Ein zwergischer Prospektor, der wenige Schritte von Yeh'kinya entfernt steht, hat die Prophezeiung ebenfalls studiert. Er sagt, es gebe sechs Tafeln von Mosh'aru, nicht zwei, und der Troll habe nicht die ganze Wahrheit gesagt.]=],
		},
	},
	mentions = {
		{ text = "Das uralte Ei" },
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "der Gott, dessen Essenz er sammelt" },
		{ id = "avatar-of-hakkar", name = "Avatar von Hakkar", note = "dessen Essenz sein Ei füllt" },
		{ id = "prospector-ironboot", name = "Prospektor Ironboot", note = "zweifelt an seinem Wort" },
	},
})

Translate("deDE", "senior-surveyor-fizzledowser", {
	title = "Obervermesser Fizzledowser",
	subtitle = "Wassergesellschaft von Gadgetzan",
	found = "Gadgetzan, auf der Westseite der Stadt",
	hint = "Sucht den Goblin, der die Wüste nach neuem Wasser vermisst.",
	allegiance = "Wassergesellschaft von Gadgetzan · Gadgetzan",
	aliases = { "Fizzledowser" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Obervermesser Fizzledowser leitet für {link:gadgetzan-water-company}die Wassergesellschaft{/link} von {link:gadgetzan}Gadgetzan{/link} die Suche nach Wasser in der Wüste. Da {link:wastewander-nomads}die Nomaden{/link} die Brunnen halten, schickt er Jungvermesser mit Wünschelgeräten in den Sand, um freie Becken und Quellen zu finden. Was sie gefunden haben, ist eine Bedrohung, weit größer als jeder Nomade.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fizzledowser ist der Goblin, der als Erster wegen der Insekten von {link:tanaris}Tanaris{/link} Alarm schlug. Zunächst tat er die Berichte über seltsame Käferwesen, die Wasser aufsaugten, als weiteren Trick der Nomaden ab. Dann begannen seine Vermesser zu sterben. Seine Berichte und die von {link:alchemist-pestlezugg}Alchemist Pestlezugg{/link} haben den Namen der {link:qiraji}Sillithid{/link} von {link:gadgetzan}Gadgetzan{/link} bis nach {link:orgrimmar}Orgrimmar{/link} und {link:darnassus}Darnassus{/link} getragen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte einen Vermesser, um das Becken nahe der {link:sandsorrow-watch}Sandsorrow-Wache{/link} zu prüfen, wo der erste Insektenangriff erfolgte.
• Er ließ Teile der Insekten aus dem Giftigen Unterschlupf zur Untersuchung sammeln.
• Er verlor seinen besten Gehilfen, Jungvermesser Scrimshank, in der Klaffenden Schlucht.
• Er willigte ein, den Insektenbericht frei weiterzugeben, gegen jede Gewohnheit seines Gewerbes.]=],
		},
	},
	chapters = {
		{
			title = "Die Wasservermessung",
			hint = [=[Zapft für die Wassergesellschaft das Becken nahe dem Wachturm der Trolle an.]=],
			text = [=[Der Vermesser, der zum Becken bei der {link:sandsorrow-watch}Sandsorrow-Wache{/link} ging, wurde von einer Kreatur aus dem Sand überfallen. Fizzledowser gab zu, dass er von solchen Kreaturen gehört hatte. Er hatte es nicht geglaubt. Nun glaubte er es, und er fürchtete, was es für die Gesellschaft bedeutete.]=],
		},
		{
			title = "Scrimshanks Erlösung",
			hint = [=[Findet heraus, was aus dem in der Klaffenden Schlucht verschollenen Vermesser wurde.]=],
			text = [=[Scrimshank war in die {link:the-gaping-chasm}Klaffende Schlucht{/link} gegangen, und sein letzter Bericht sprach von weiteren Insekten dort. Nur seine Vermessungsausrüstung kam zurück. Fizzledowser ordnete die Habseligkeiten des jungen Goblins selbst. Die Aufzeichnungen, die Scrimshank hinterließ, deuteten darauf hin, dass die Insekten unter der Kontrolle einer dritten Macht stehen könnten.]=],
		},
		{
			title = "Der Aufstieg der Sillithid",
			hint = [=[Bringt den Bericht über die Insekten zu den Gelehrten der großen Städte.]=],
			text = [=[{link:alchemist-pestlezugg}Pestlezugg{/link} bat darum, dass jeder, der lesen könne, den Bericht sehen solle. Fizzledowser, der Wissen gewöhnlich für gutes Geld verkaufte, fertigte Abschriften an und schickte sie an die Gelehrten, die er in den Hauptstädten kannte. Von ihnen kam der Name des Feindes.]=],
		},
	},
	mentions = {
		{ text = "Untersuchung des Giftigen Unterschlupfs" },
		{ text = "Analyse von Insektenteilen" },
	},
	bonds = {
		{ id = "alchemist-pestlezugg", name = "Alchemist Pestlezugg", note = "erforscht mit ihm die Insekten" },
		{ id = "chief-engineer-bilgewhizzle", name = "Chefingenieur Bilgewhizzle", note = "Mitoffizier der Wassergesellschaft" },
	},
})

Translate("deDE", "chief-engineer-bilgewhizzle", {
	title = "Chefingenieur Bilgewhizzle",
	subtitle = "Wassergesellschaft von Gadgetzan",
	found = "Gadgetzan, unter dem Wasserturm",
	hint = "Sucht den Ingenieur, der das Wasser von Gadgetzan hütet.",
	allegiance = "Wassergesellschaft von Gadgetzan · Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Chefingenieur Bilgewhizzle unterhält die Brunnen und Energiequellen der {link:gadgetzan-water-company}Wassergesellschaft von Gadgetzan{/link}, und er führt ihren Krieg gegen {link:wastewander-nomads}die Nomaden{/link} der Wastewander. Er ist laut, jähzornig und durstig, und er gibt nichts umsonst her. Er hat das Kopfgeld auf {link:caliph-scorpidsting}Kalif Scorpidsting{/link} ausgesetzt. Außerdem findet er neue Wasserlöcher mit einer Wünschelrute eigener Bauart, und er will sie von dem Abenteurer zurück, der sie sich lieh und nach {red:zul-farrak}Zul'Farrak{/red} mitnahm.]=],
		},
	},
	chapters = {
		{
			title = "Gerechtigkeit für die Wastewander",
			hint = [=[Verschafft der Wassergesellschaft Gerechtigkeit gegen die Nomaden.]=],
			text = [=[Die Nomaden hatten fast jeden Brunnen an sich gerissen. Bilgewhizzle wollte ihre Zahl verringert sehen, zuerst die Banditen und Diebe, dann die Schurken und Schattenmagier, bis die Gesellschaft den Kampf zu ihnen tragen konnte.]=],
		},
	},
	mentions = {
		{ text = "Den Durst stillen" },
		{
			text = [=[Mehr Gerechtigkeit für die {link:wastewander-nomads}Wastewander{/link}]=],
		},
		{ text = "GESUCHT: {link:caliph-scorpidsting}Kalif Scorpidsting{/link}" },
		{ text = "Divino-matische Rute" },
	},
})

Translate("deDE", "alchemist-pestlezugg", {
	title = "Alchemist Pestlezugg",
	subtitle = "Alchemiebedarf",
	found = "Gadgetzan",
	hint = [=[Sucht den Alchemisten von Gadgetzan, der die Insekten der Wüste erforscht.]=],
	allegiance = "Gadgetzan",
	aliases = { "Pestlezugg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alchemist Pestlezugg ist ein Goblinalchemist aus {link:gadgetzan}Gadgetzan{/link} und ein alter Freund von {link:senior-surveyor-fizzledowser}Obervermesser Fizzledowser{/link}. Als ihm die Insekten aus dem Giftigen Unterschlupf gebracht wurden, sah er, dass sie durch eine fremde Macht zu reinen Verwüstern verwandelt worden waren. Er warnte, dass sie ganz das südliche {link:kalimdor}Kalimdor{/link} bedrohten. Er erfuhr, dass die Insekten wie Bienen sind: Tötet man die Königin, verfällt der Stock in Unordnung.]=],
		},
	},
	chapters = {
		{
			title = "Bauer schlägt Königin",
			hint = [=[Ruft die Königin des Gorishi-Stocks herbei und erschlagt sie.]=],
			text = [=[Pestlezugg braute einen Köder aus einer Duftdrüse und der Erde des {link:un-goro-crater}Un'Goro-Kraters{/link}. Damit wurde die Königin des Gorishi-Stocks hervorgelockt und erschlagen, und ihr Gehirn wurde nach {link:gadgetzan}Gadgetzan{/link} gebracht. Er feierte nicht. Er hielt den Sieg für zu glatt und die Sillithid für längst nicht besiegt.]=],
		},
	},
	mentions = {
		{ text = "Pfusch im Dschungel" },
		{ text = "Die Ruhe vor dem Sturm" },
	},
})

Translate("deDE", "sprinkle", {
	title = "Sprinkle",
	found = "Gadgetzan",
	hint = [=[Sucht die Köchin von Gadgetzan, die eine geheime Zutat hütet.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sprinkle ist eine Köchin aus {link:gadgetzan}Gadgetzan{/link} und eine Freundin von {link:marin-noggenfogger}Marin Noggenfogger{/link}. Als Kind überlebte sie die Kochkünste ihrer Schwester, indem sie eine geheime Zutat fand: den Violetten Tragan, einen Pilz, der nur unter dem Wasser eines Sees im {link:the-hinterlands}Hinterland{/link} wächst. Es war ihr violettes Pulver, das Noggenfoggers fauligen Tau in das Elixier verwandelte, das seinen Namen trägt. Er schuldet ihr einen Gefallen. Er scheint sich nicht daran zu erinnern.]=],
		},
	},
	bonds = {
		{ id = "marin-noggenfogger", name = "Marin Noggenfogger", note = "schuldet ihr einen Gefallen" },
	},
})

Translate("deDE", "tran-rek", {
	title = "Tran'rek",
	found = "Gadgetzan",
	hint = [=[Sucht den Trollhändler von Gadgetzan, der immer einen neuen Plan hat.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tran'rek ist ein Troll, der in {link:gadgetzan}Gadgetzan{/link} Handel treibt und von leichtem Gold träumt. {link:krazek}Krazek{/link} aus {link:booty-bay}Booty Bay{/link} nennt ihn Vetter, und Tran'rek schuldet ihm eine Ladung Skarabäuspanzer. Die Skarabäen von {link:tanaris}Tanaris{/link} wurden wegen ihrer harten Panzer fast bis zum Aussterben gejagt, doch Tran'rek weiß, wo noch eine Kolonie lebt: in {red:zul-farrak}Zul'Farrak{/red}. Außerdem will er ins {link:thistleshrub-valley}Disteltal{/link} gelangen, und er hat einen Plan, superklebrigen Teer aus dem {link:un-goro-crater}Un'Goro-Krater{/link} zu verkaufen und danach ein Mittel, um ihn zu entfernen.]=],
		},
	},
	mentions = {
		{ text = "Tran'rek" },
		{ text = "Skarabäuspanzer" },
		{ text = "{link:thistleshrub-valley}Disteltal{/link}" },
		{ text = "Superklebrig" },
	},
	bonds = {
		{ id = "krazek", name = "Krazek", note = "sein Vetter, dem er eine Lieferung schuldet" },
	},
})

Translate("deDE", "trenton-lighthammer", {
