Translate("deDE", "krinkle-goodsteel", {
	title = "Krinkle Goodsteel",
	found = "Gadgetzan, neben der Schmiede",
	hint = [=[Sucht den Goblinschmied von Gadgetzan, der seine Kunst an den Meistbietenden verkauft.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krinkle Goodsteel ist ein Goblinschmied aus {link:gadgetzan}Gadgetzan{/link}, der sein Können an den Meistbietenden verkauft. Sein Verzeichnis gesuchter Waren ist bis in die {link:searing-gorge}Sengende Schlucht{/link} gelangt, wo {link:locheed}Locheed{/link} einst den Auftrag annahm. Er fertigte die Gussform für den Skelettschlüssel, den {link:alchemist-arbington}Alchemist Arbington{/link} und {link:apothecary-dithers}Apotheker Dithers{/link} gegen den Lich von {link:ruins-of-andorhal}Andorhal{/link} brauchten, für eine Gebühr von fünfzehn Gold. Er wies die Träger an, ihn in den Lavasee auf dem Feuerfedergrat im {link:un-goro-crater}Un'Goro-Krater{/link} zu tauchen, wo die Hitze Thorium und Knochen verschmelzen würde.]=],
		},
	},
	mentions = {
		{ text = "Verzeichnis aus {link:tanaris}Tanaris{/link}" },
		{ text = "Gussform reimt sich auf ..." },
		{ text = "Im Feuerfedergrat geschmiedet" },
	},
})

Translate("deDE", "shreev", {
	title = "Shreev",
	found = "Das Gizmorium von Gadgetzan",
	hint = [=[Sucht den Goblin des Gizmoriums, der Sprengstoffe für Rennfahrer baut.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shreev betreibt das Gizmorium von {link:gadgetzan}Gadgetzan{/link}. Er baut Sprengstoffe, und zu seinen Kunden gehören die Goblinrennfahrer der {link:the-shimmering-flats}Schimmernden Ebene{/link}. {link:razzeric}Razzeric{/link} bestellte bei ihm einen Seaforiumverstärker. Shreev hatte ihn bereits stärker gemacht, als sicher war, und baute eine Sicherung ein. Razzeric schickte ihn zurück. Shreev entfernte die Sicherung und warnte, dass ein einziger Fehler von dem Rennfahrer nur einen verbrannten Fleck auf der Strecke übrig lassen würde.]=],
		},
	},
	mentions = {
		{ text = "Sicherheit geht vor" },
	},
	bonds = {
		{ id = "razzeric", name = "Razzeric", note = "sein waghalsigster Kunde" },
	},
})

Translate("deDE", "vizzklick", {
	title = "Vizzklick",
	subtitle = "Schneiderbedarf",
	found = "Gadgetzan",
	hint = "Sucht den Stoffhändler von Gadgetzan.",
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vizzklick verkauft in {link:gadgetzan}Gadgetzan{/link} Stoffe und Schneiderwaren. Er ist ein ehrlicher Händler, oder zumindest hält er sich für einen, und jahrelang sah er zu, wie {link:trade-master-kovic}Handelsmeister Kovic{/link} vom Untermarkt jeden Händler der Welt unterbot. Als {link:nilith-lokrav}Nilith Lokrav{/link} Nachricht schickte, dass Kovic tot sei, nannte Vizzklick es einen herrlichen Tag und belohnte den Überbringer der Nachricht großzügig.]=],
		},
	},
	mentions = {
		{ text = "Der Untermarkt" },
	},
	bonds = {
		{ id = "trade-master-kovic", name = "Handelsmeister Kovic", note = "der Rivale, dessen Tod er feierte" },
	},
})

Translate("deDE", "andi-lynn", {
	title = "Andi Lynn",
	found = "Gadgetzan",
	hint = [=[Sucht die Person in Gadgetzan, die die Oger des Südens beobachtet.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Andi Lynn behält von {link:gadgetzan}Gadgetzan{/link} aus die {link:ogres}Oger{/link} der südlichen Wüste im Auge. Eine große Schar nomadischer Oger der Dünenbrecher ist in {link:tanaris}Tanaris{/link} angekommen und hat im Süden ein Truppenlager errichtet, und kleinere Scharen haben sich in die alten Trollruinen ausgebreitet. Sie glaubt, dass das Lager zerstört werden muss, bevor die Oger ihre Kräfte sammeln, und dass der Tod ihres Anführers, {link:gor-marok-the-ravager}Gor'marok{/link} des Verwüsters, der Anfang ihres Endes wäre.]=],
		},
	},
	chapters = {
		{
			title = "Das Truppenlager der Dünenbrecher",
			hint = "Zerschlagt das Ogerlager im Süden.",
			text = [=[Die Rohlinge und Vollstrecker des Lagers fielen, und {link:gor-marok-the-ravager}Gor'marok{/link} mit ihnen. Andi Lynn war froh darüber.]=],
		},
	},
	bonds = {
		{ id = "gor-marok-the-ravager", name = "Gor'marok der Verwüster", note = "der Oger, den sie tot sehen will" },
	},
})

Translate("deDE", "marvon-rivetseeker", {
	title = "Marvon Rivetseeker",
	found = "Die Zerbrochene Säule, mitten in der Wüste",
	hint = [=[Sucht den Goblingelehrten, der zwischen den Trollruinen der Wüste lagert.]=],
	allegiance = "Ratchet",
	aliases = { "Marvon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marvon Rivetseeker ist ein Goblin aus {link:ratchet}Ratchet{/link}, ein Wissenschaftler und nach eigener Aussage im Herzen ein Schatzsucher. Er hat viele alte Stätten der Welt erforscht und lagert nun in der Wüste, um ihre Trollruinen zu studieren. Er sammelt die Schmuckstücke aus Gahz'ridian, einem Stein, den die {link:trolls}Trolle{/link} in der Gestalt ihres Hydragottes schnitzten, und er hat einen Helm gebaut, der sie aufspürt. Einst betrat er den {link:temple-of-atal-hakkar}Versunkenen Tempel{/link} und entkam nur knapp. An seinen Kreis aus Schlangenstatuen erinnert er sich nur bruchstückhaft.]=],
		},
	},
	chapters = {
		{
			title = "Der Steinkreis",
			hint = [=[Helft dem Goblingelehrten, sich an den Versunkenen Tempel zu erinnern.]=],
			text = [=[Marvon hatte einen runden Stein gefunden, der mit demselben Schlangenzeichen versehen war, das er im Tempel gesehen hatte, und ihn in seine Werkstatt in {link:ratchet}Ratchet{/link} verschifft. Als er ihm gebracht wurde, kehrte seine Erinnerung zurück: sechs Balkone, sechs Schlangenstatuen und darunter ein Altar Hakkars.]=],
		},
	},
	mentions = {
		{ text = "Gahz'ridian" },
		{ text = "Der Versunkene Tempel" },
		{ text = "In die Tiefen" },
		{ text = "Das Geheimnis des Kreises" },
	},
})

Translate("deDE", "stoley", {
	title = "Stoley",
	found = "Steamwheedle, hinter der Theke",
	hint = "Sucht den Wirt von Steamwheedle.",
	allegiance = "Steamwheedle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stoley steht in {link:steamwheedle-port}Steamwheedle{/link} hinter der Theke. Einst wettete er mit seinem alten Freund {link:sea-wolf-mackinley}„Seewolf“ MacKinley{/link} aus {link:booty-bay}Booty Bay{/link}, dass der Rum von {link:kalimdor}Kalimdor{/link} stärker sei als alles in Booty Bay, und er versprach, seine Schuld zu verdoppeln, falls MacKinley anderer Meinung sei. Dann stahl der Pirat Kapitän Cuergo seine letzte Lieferung und versteckte sie in der {link:lost-rigger-cove}Lost-Rigger-Bucht{/link}. Als endlich eine Flasche Booty Bay erreichte, nannte MacKinley den Rum schrecklich und gab die Wette verloren.]=],
		},
	},
	mentions = {
		{ text = "Stoleys Schuld" },
		{ text = "Stoleys Lieferung" },
		{ text = "Lieferung an {link:sea-wolf-mackinley}MacKinley{/link}" },
	},
	bonds = {
		{ id = "sea-wolf-mackinley", name = "„Seewolf“ MacKinley", note = "sein alter Freund und Rivale bei Wetten" },
	},
})

Translate("deDE", "security-chief-bilgewhizzle", {
	title = "Sicherheitschef Bilgewhizzle",
	subtitle = "Sicherheitsdienst der Wassergesellschaft",
	found = "Steamwheedle",
	hint = "Sucht den Goblin, der in Steamwheedle den Frieden wahrt.",
	allegiance = "Wassergesellschaft von Gadgetzan · Steamwheedle-Kartell",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sicherheitschef Bilgewhizzle wahrt den Frieden in {link:steamwheedle-port}Steamwheedle{/link}. Er kann die Docks nicht verlassen, und so bezahlt er Fremde dafür, sich um die Piraten der {link:lost-rigger-cove}Lost-Rigger-Bucht{/link} zu kümmern. Nach einem Erlass des Hafens und Gadgetzans nimmt er den Kopf des Piratenkapitäns {link:andre-firebeard}Andre Firebeard{/link} anstelle des Piraten selbst entgegen, und er zahlt dafür nach einer Unterschrift unter einen Vertrag mit sehr kleinem Kleingedruckten. Er war froh, die Fahrpläne zu erhalten, die die Piraten gestohlen hatten, und beunruhigt zu erfahren, wie sie an sie gekommen waren.]=],
		},
	},
	mentions = {
		{ text = "GESUCHT: {link:andre-firebeard}Andre Firebeard{/link}" },
		{ text = "Fahrpläne" },
		{ text = "{link:southsea-pirates}Südmeer{/link}-Schutzgeld" },
	},
	bonds = {
		{ id = "andre-firebeard", name = "Andre Firebeard", note = "der Pirat, dessen Kopf er will" },
	},
})

Translate("deDE", "prospector-ironboot", {
	title = "Prospektor Ironboot",
	found = "Steamwheedle",
	hint = [=[Sucht den zwergischen Prospektor von Steamwheedle, der alte Tafeln studiert.]=],
	allegiance = "Unbekannt",
	aliases = { "Ironboot" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektor Ironboot ist ein {link:dwarves}Zwerg{/link}, der sich in {link:steamwheedle-port}Steamwheedle{/link} niedergelassen hat, wenige Schritte von dem Troll {link:yeh-kinya}Yeh'kinya{/link} entfernt. Er hat die Prophezeiung von Mosh'aru lange studiert, und er hat herausgefunden, dass sie auf sechs Tafeln geschrieben wurde, nicht auf zwei. Die Tafeln, die Yeh'kinya sammelte, sprachen davon, die Essenz von {link:hakkar}Hakkar{/link} zu halten. Ironboot fürchtet, dass die anderen dunklere Geheimnisse bergen, und er glaubt, dass der Troll nicht die Wahrheit gesagt hat.]=],
		},
	},
	chapters = {
		{
			title = "Die verlorenen Tafeln von Mosh'aru",
			hint = "Findet die Tafeln, von denen der Troll nie sprach.",
			text = [=[Die dritte und vierte Tafel wurden von den Trollen der Mossflayer in den {link:eastern-plaguelands}Östlichen Pestländern{/link} gehalten. Die fünfte und sechste lagen bei den Trollen der Smolderthorn in der {link:blackrock-mountain}Blackrockspitze{/link}. Ironboot las sie alle. Was er erfuhr, sagte er, bedeute, dass ein Held gebraucht werde.]=],
		},
	},
	mentions = {
		{ text = "Die letzten Tafeln" },
	},
	bonds = {
		{ id = "yeh-kinya", name = "Yeh'kinya", note = "an dessen Wort er zweifelt" },
	},
})

Translate("deDE", "nixx-sprocketspring", {
	title = "Nixx Sprocketspring",
	subtitle = "Meister der Goblin-Ingenieurskunst",
	found = "Gadgetzan",
	hint = "Sucht den Meister der Goblin-Ingenieurskunst in Gadgetzan.",
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nixx Sprocketspring ist der Meister der Goblin-Ingenieurskunst in {link:gadgetzan}Gadgetzan{/link}. Seine Schule schätzt praktischen Nutzen, hohen Gewinn und noch höhere Sprengkraft. Ihre Geheimnisse sind durch einen alten Eid gebunden: Wer ihn schwört, darf niemals die gnomische Disziplin erlernen. Nixx blickt auf die Ingenieure von {link:gnomeregan}Gnomeregan{/link} herab, deren Heimat, wie er sagt, beweist, dass jeder die Grundlagen lernen kann. Meisterschaft, sagt er, erfordert einen starken Verstand und eine sehr ruhige Hand.]=],
		},
	},
	mentions = {
		{ text = "Goblin-Ingenieurskunst" },
		{ text = "Das Gelöbnis der Verschwiegenheit" },
	},
})

Translate("deDE", "wharfmaster-steamfizzle", {
	title = "Kaimeister Steamfizzle",
	found = "Steamwheedle, am Kai",
	hint = "Sucht den Kaimeister von Steamwheedle.",
	allegiance = "Steamwheedle-Kartell",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kaimeister Steamfizzle verwaltet den Kai von {link:steamwheedle-port}Steamwheedle{/link}. In diesen Tagen segeln die Schiffe des Kartells von der Wüste über das Meer nach {link:powderfuse-port}Powderfuse Port{/link} in den {link:riverglades}Riverglades{/link}, wo ein anderer Kaimeister sie erwartet.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Wenig ist über Steamfizzle geschrieben, außer über den Kai, den er verwaltet.]=],
		},
	},
})

Translate("deDE", "stone-watcher-of-norgannon", {
	title = "Steinwächter von Norgannon",
	found = "Das Tal der Behüter, vor den versiegelten Toren von Uldum",
	hint = [=[Bringt die Platinscheiben zum Sockel vor den versiegelten Toren.]=],
	allegiance = "Die Titanen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Steinwächter von Norgannon ist ein Hüter des Zugangs nach {link:valley-of-the-watchers}Uldum{/link}. Er erscheint am Sockel vor den versiegelten Toren, wenn die Platinscheiben von {link:uldaman}Uldaman{/link} dorthin gebracht werden. Er spricht mit Macht und Autorität. Er lässt niemanden in die Anlage von Uldum, der nicht die Platten von Uldum mit den Scheiben vereint hat. Wo diese Platten zu finden sein könnten, sagt er nicht, und die Weisen von {link:thunder-bluff}Thunder Bluff{/link} wissen es noch nicht.]=],
		},
	},
	bonds = {
		{ id = "lore-keeper-of-norgannon", name = "Hüter des Wissens von Norgannon", note = "eine andere Stimme derselben Scheiben" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "schickte die Scheiben zu den Toren" },
		{ id = "sage-truthseeker", name = "Weiser Truthseeker", note = "erforscht die Scheiben" },
	},
})

Translate("deDE", "caliph-scorpidsting", {
	title = "Kalif Scorpidsting",
	found = "Die östliche Wüste, zwischen den Lagern der Wastewander",
	hint = [=[Stellt Euch dem Anführer der Nomaden, die die Brunnen halten.]=],
	allegiance = "Nomaden der Wastewander",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kalif Scorpidsting führt {link:wastewander-nomads}die Nomaden{/link} der Wastewander an. Unter ihm nahmen die Gesetzlosen die Brunnen der östlichen Wüste ein, töteten die Arbeiter der {link:gadgetzan-water-company}Wassergesellschaft von Gadgetzan{/link} und trugen ihr Wasser fort. Die Gesellschaft hat ihn auf einem Steckbrief wegen Mordes, Diebstahls und der Beschlagnahme ihres Eigentums genannt. Sie glaubt, dass sein Tod die Nomaden endlich von ihren Brunnen vertreiben könnte.]=],
		},
	},
	mentions = {
		{ text = "GESUCHT: Kalif Scorpidsting" },
	},
	bonds = {
		{ id = "chief-engineer-bilgewhizzle", name = "Chefingenieur Bilgewhizzle", note = "bezahlt für seinen Kopf" },
	},
})

Translate("deDE", "gor-marok-the-ravager", {
	title = "Gor'marok der Verwüster",
	found = "Das Truppenlager der Dünenbrecher, in der südlichen Wüste",
	hint = [=[Stellt Euch dem Häuptling der Oger im südlichen Truppenlager.]=],
	allegiance = "Oger der Dünenbrecher",
	aliases = { "Gor'marok" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gor'marok der Verwüster führt die {link:ogres}Oger{/link} der Dünenbrecher an, die in die südliche {link:tanaris}Wüste von Tanaris{/link} gekommen sind. Unter ihm haben sie ein Truppenlager ummauert und Scharen über den Sand und in die alten Trollruinen ausgesandt. {link:gadgetzan}Gadgetzan{/link} glaubt, dass sein Fall der Anfang vom Ende der Oger wäre.]=],
		},
	},
	bonds = {
		{ id = "andi-lynn", name = "Andi Lynn", note = "will ihn tot sehen" },
	},
})

Translate("deDE", "andre-firebeard", {
	title = "Andre Firebeard",
	found = "Lost-Rigger-Bucht",
	hint = "Stellt Euch dem Piratenkapitän der Lost-Rigger-Bucht.",
	allegiance = "Südmeerpiraten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Andre Firebeard ist ein Kapitän der {link:southsea-pirates}Südmeerpiraten{/link} der {link:lost-rigger-cove}Lost-Rigger-Bucht{/link}. Er wird von {link:steamwheedle-port}Steamwheedle{/link} und von {link:gadgetzan}Gadgetzan{/link} wegen Verbrechen gegen beide gesucht. Durch Erlass ihres Rates darf jeder, der die Bekanntmachung liest, tödliche Gewalt gegen ihn anwenden, und sollte er vor seiner Anhörung sterben, darf sein Kopf an seiner Stelle vor Gericht stehen.]=],
		},
	},
	bonds = {
		{ id = "security-chief-bilgewhizzle", name = "Sicherheitschef Bilgewhizzle", note = "erwartet seinen Kopf" },
	},
})
